/** Bubble image for a count (places navy, events gold). */
export function clusterImage(kind: 'place' | 'event', count: number): MarkerImage {
  const list = kind === 'place' ? PLACE_CLUSTER_IMAGES : EVENT_CLUSTER_IMAGES;
  return list[Math.min(Math.max(count, 2), MAX_CLUSTER_IMAGE) - 2];
}
